def _resolve_data_state(self, state):
    if isinstance(state, str):
        return next((s for s in self.states_map.values() if s.id == state), None)
    return next((s for s in self.states_map.values() if s is state or s is getattr(state, "_state", None)), None)

def get_state_data(self, state):
    state = self._resolve_data_state(state)
    return self._state_data.get(state.id) if state is not None else None

@property
def state_data_values(self):
    return deepcopy(self._state_data)

def set_state_data(self, state, key, value):
    state = self._resolve_data_state(state)
    if state is None or state.id not in self._state_data:
        raise InvalidDefinition("State is not active")
    if key not in state.data:
        raise InvalidDefinition(f"Undeclared state data key: {key!r}")
    declaration = state.data[key]
    if isinstance(declaration, DataVar):
        declaration.validate(value)
    values = self._state_data[state.id]
    self._data_changes.append(DataChangeInfo(state.id, key, deepcopy(values[key]), deepcopy(value)))
    values[key] = value

def get_data_changes(self):
    return list(self._data_changes)

def _enter_state_data(self, state, restored=None):
    if restored is not None:
        self._state_data[state.id] = deepcopy(restored)
        return
    self._state_data[state.id] = {
        key: value.initial_value() if isinstance(value, DataVar)
        else value() if callable(value) else deepcopy(value)
        for key, value in state.data.items()
    }

def _data_scope(self, state):
    values = {}
    if state is not None:
        for current in reversed([state, *state.ancestors()]):
            values.update(self._state_data.get(current.id, {}))
    return values

